"""Generate the shared theme stylesheet and the living color guide."""
from pathlib import Path
import json
ROOT = Path(__file__).resolve().parent

def generate():
    data=json.loads((ROOT/'design-tokens.json').read_text())
    def block(selector, values):
        return selector+' {\n'+''.join(f'  --{k}: {v};\n' for k,v in values.items())+'}\n'
    css='/* Generated by design-system.py from design-tokens.json. Do not edit. */\n'
    css+=block(':root',data['primitives'])
    css+=block(':root, html[data-theme="light"]',data['themes']['light'])
    css+='html[data-theme="light"] { color-scheme: light; }\n'
    css+=block('html[data-theme="dark"]',data['themes']['dark'])
    css+='html[data-theme="dark"] { color-scheme: dark; }\n'
    css+='@media print {\n'+block(':root, html[data-theme]',data['themes']['light'])+'html[data-theme] { color-scheme: light; }\n}\n'
    css+=(ROOT/'color-components.css').read_text()
    (ROOT/'dist/design-system.css').write_text(css)

def render(write, heading, panel):
    concepts=[('connect','Connections','Mind mapping','Connect ideas and explain the relationship.'),('explain','Explanation','Feynman technique','Explain an idea in your own words.'),('compare','Comparison','Interleaving','Compare situations and choose a method.'),('recall','Recall','Retrieval + spacing','Try without notes, then return after a gap.')]
    body=heading('COLOR & MEANING','A shared language<br><em>for complex ideas.</em>','Concept colors use teal, blue, and purple. Recall uses a second blue shade. The same concept keeps its color in every lesson, diagram, and theme. Use the sun or moon in the header to compare modes.')
    body+='<div class="concept-key" aria-label="Concept color key">'+''.join(f'<span class="concept-badge" data-concept="{k}">{n}</span>' for k,n,_,_ in concepts)+'</div>'
    body+='<div class="color-guide-grid">'+''.join(f'<article class="concept-callout" data-concept="{k}"><span class="eyebrow">{n}</span><h2>{title}</h2><p>{desc}</p><p><span class="concept-text">Colored text</span> · <mark class="concept-highlight">A key idea</mark></p></article>' for k,n,title,desc in concepts)+'</div>'
    body+=panel('Read the relationship','<p><span class="concept-text" data-concept="connect">Mind mapping connects ideas</span>; <span class="concept-text" data-concept="explain">explanation tests their meaning</span>. <span class="concept-text" data-concept="compare">Comparison helps you choose</span>, and <mark class="concept-highlight" data-concept="recall">recall checks what remains after a gap</mark>.</p><p class="small-note">Color supports the words. Labels, arrows, and examples still carry the meaning.</p>')
    body+=panel('Feedback has its own meaning','<div class="color-guide-grid"><div class="status-callout" data-status="success"><strong>✓ Successful attempt</strong><p>You explained it without help. Try a new situation.</p></div><div class="status-callout" data-status="warning"><strong>! Check this step</strong><p>A hint helped. Try another question independently.</p></div><div class="status-callout" data-status="error"><strong>× Needs correction</strong><p>Check the missing idea, then try again.</p></div></div>')
    body+=panel('A quiet foundation','<div class="neutral-samples"><div>Page canvas</div><div>Reading surface</div><div>Raised surface</div></div><p class="small-note">Blue is also the shared interaction color. Concept colors identify ideas; feedback labels describe an outcome.</p>')
    body+=panel('Use color with intention','<p>Keep long explanations in the default text color. Highlight a short phrase or an important relationship. Use a labeled badge when several concepts appear together. Keep these meanings consistent when adding lessons.</p><p>These themes adapt Daniel Wodziczka’s color system for Software Mansion: <a class="text-link" href="https://dribbble.com/shots/21283572-Design-System-Color-Palette-Light-Mode">Light palette ↗</a> · <a class="text-link" href="https://dribbble.com/shots/21284305-Design-System-Color-Palette-Dark-Mode">Dark palette ↗</a>. Soft dark surfaces and some text shades are adapted for this site’s contrast needs.</p>')
    write('design-system','Color & meaning',body)
